import 'dart:async';

import 'package:built_collection/built_collection.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:geolocator/geolocator.dart';
import 'package:riverpod_annotation/riverpod_annotation.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';

import 'package:ukcheckpoints_app/core/utils/logger.dart';
import 'package:ukcheckpoints_app/features/checkpoints/data/checkpoint_repository.dart';
import 'package:ukcheckpoints_app/features/checkpoints/domain/checkpoint_error.dart';
import 'package:ukcheckpoints_app/features/checkpoints/domain/geoutils.dart';

part 'checkpoint_provider.g.dart';

class CheckpointState {
  final List<Checkpoint> checkpoints;
  final int total;
  final bool isSyncing;

  const CheckpointState({
    required this.checkpoints,
    required this.total,
    this.isSyncing = false,
  });

  CheckpointState copyWith({
    List<Checkpoint>? checkpoints,
    int? total,
    bool? isSyncing,
  }) {
    return CheckpointState(
      checkpoints: checkpoints ?? this.checkpoints,
      total: total ?? this.total,
      isSyncing: isSyncing ?? this.isSyncing,
    );
  }
}

@Riverpod(keepAlive: true)
class CheckpointNotifier extends _$CheckpointNotifier {
  int _syncToken = 0;

  @override
  FutureOr<CheckpointState> build() async {
    return _synchronizeLedger();
  }

  Future<CheckpointState> _synchronizeLedger() async {
    final currentToken = ++_syncToken;

    try {
      final repo = ref.read(checkpointRepositoryProvider);
      final result = await repo.fetchCheckpoints();

      final checkpoints = result.checkpoints;
      final totalCount = result.total == 0 ? checkpoints.length : result.total;

      final state = CheckpointState(
        checkpoints: checkpoints,
        total: totalCount,
        isSyncing: result.cursor != null && result.cursor!.isNotEmpty,
      );

      if (state.isSyncing) {
        unawaited(_exhaustCursor(result.cursor!, currentToken));
      }

      return state;
    } on CheckpointError catch (e, st) {
      AppLogger.error('Checkpoint provider error', error: e, stackTrace: st);
      rethrow;
    } catch (e, st) {
      AppLogger.error('Checkpoint provider error', error: e, stackTrace: st);
      throw const CheckpointSyncError();
    }
  }

  Future<void> _exhaustCursor(String cursor, int token) async {
    String? currentCursor = cursor;
    final repo = ref.read(checkpointRepositoryProvider);

    while (currentCursor != null && currentCursor.isNotEmpty) {
      if (token != _syncToken) break;

      try {
        final result = await repo.fetchCheckpoints(cursor: currentCursor);
        final newItems = result.checkpoints;
        currentCursor = result.cursor;

        final previousState = state.value;
        if (previousState != null && token == _syncToken) {
          final existingIds =
              previousState.checkpoints.map((e) => e.id).toSet();
          final uniqueNewItems =
              newItems.where((item) => !existingIds.contains(item.id)).toList();

          state = AsyncData(
            previousState.copyWith(
              checkpoints: [...previousState.checkpoints, ...uniqueNewItems],
              isSyncing: currentCursor != null && currentCursor.isNotEmpty,
            ),
          );
        }
      } catch (e, st) {
        AppLogger.error(
          'Error fetching checkpoint events',
          error: e,
          stackTrace: st,
        );
        break;
      }
    }
  }

  Future<void> refresh() async {
    state = const AsyncLoading();
    state = await AsyncValue.guard(_synchronizeLedger);
  }

  Future<void> contribute(
    String checkpointId,
    ContributionStatusEnum status,
  ) async {
    try {
      final repo = ref.read(checkpointRepositoryProvider);
      _optimisticUpdate(checkpointId, status);
      await repo.contribute(checkpointId, status);
    } on CheckpointError {
      rethrow;
    } catch (e, st) {
      AppLogger.error('Checkpoint contribute error', error: e, stackTrace: st);
      throw const CheckpointTransmissionError();
    }
  }

  void _optimisticUpdate(String id, ContributionStatusEnum newStatus) {
    updateFromRealtime(id, newStatus, DateTime.now().toUtc());
  }

  void updateFromRealtime(
    String id,
    ContributionStatusEnum newStatus,
    DateTime createdAt,
  ) {
    final currentState = state.value;
    if (currentState == null) return;

    final index = currentState.checkpoints.indexWhere((c) => c.id == id);
    if (index == -1) return;

    final updatedList = List<Checkpoint>.from(currentState.checkpoints);

    updatedList[index] = updatedList[index].rebuild((b) {
      final newContribution = Contribution(
        (c) => c..status = newStatus..createdAt = createdAt,
      );

      final currentContribs = b.contributions.build().toList();
      currentContribs.insert(0, newContribution);

      b.contributions = ListBuilder<Contribution>(currentContribs);
    });

    state = AsyncData(currentState.copyWith(checkpoints: updatedList));
  }
}

@riverpod
class CheckpointSearch extends _$CheckpointSearch {
  Timer? _timer;

  @override
  String build() {
    ref.onDispose(() => _timer?.cancel());
    return '';
  }

  void update(String query) {
    _timer?.cancel();
    final sanitized = query.trim();
    if (sanitized.isEmpty && state.isEmpty) return;
    _timer = Timer(const Duration(milliseconds: 250), () {
      if (state != sanitized) state = sanitized;
    });
  }
}

@riverpod
class CheckpointStatusFilter extends _$CheckpointStatusFilter {
  @override
  ContributionStatusEnum? build() => null;
  void setFilter(ContributionStatusEnum? status) => state = status;
}

@riverpod
class NearbyOnlyFilter extends _$NearbyOnlyFilter {
  @override
  bool build() => false;
  void toggle() => state = !state;
}

@riverpod
Stream<Position> userLocationStream(Ref ref) {
  return Geolocator.getPositionStream(
    locationSettings: const LocationSettings(
      accuracy: LocationAccuracy.high,
      distanceFilter: 10,
    ),
  );
}

@riverpod
AsyncValue<CheckpointState> filteredCheckpoints(Ref ref) {
  final query = ref.watch(checkpointSearchProvider).toLowerCase();
  final statusFilter = ref.watch(checkpointStatusFilterProvider);
  final isNearbyOnly = ref.watch(nearbyOnlyFilterProvider);
  final locationAsync = ref.watch(userLocationStreamProvider);
  final ledgerAsync = ref.watch(checkpointNotifierProvider);

  return ledgerAsync.whenData((data) {
    final userPos = locationAsync.value;

    bool matchesSearch(Checkpoint c) {
      return c.name.toLowerCase().contains(query) ||
          '${c.latitude}, ${c.longitude}'.contains(query);
    }

    bool matchesFilter(Checkpoint c) {
      if (statusFilter == null) return true;
      final latest =
          c.contributions.isNotEmpty ? c.contributions.first.status : null;
      return latest == statusFilter;
    }

    final results =
        data.checkpoints.where((c) {
          final baseMatch = matchesFilter(c) && matchesSearch(c);
          if (isNearbyOnly && userPos != null) {
            return baseMatch &&
                isWithinProximity(
                  c.latitude,
                  c.longitude,
                  userPos.latitude,
                  userPos.longitude,
                );
          }
          return baseMatch;
        }).toList();

    return data.copyWith(checkpoints: results, total: results.length);
  });
}

