1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	import 'package:flutter/services.dart';
5	import 'package:flutter_riverpod/flutter_riverpod.dart';
6	import 'package:here_sdk/core.dart';
7	import 'package:here_sdk/mapview.dart';
8	import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
9	import 'package:ukcheckpoints_app/core/theme/theme.dart';
10	import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';
11	import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_action_sheet_widget.dart';
12	import 'package:ukcheckpoints_app/features/checkpoints/widgets/nearby_checkpoint_popup.dart';
13	import 'package:ukcheckpoints_app/features/map/controllers/map_controller.dart';
14	import 'package:ukcheckpoints_app/features/map/widgets/map_overlay_buttons.dart';
15	import 'package:ukcheckpoints_app/features/map/widgets/map_search_bar.dart';
16	import 'package:ukcheckpoints_app/features/map/widgets/map_speed_overlay.dart';
17	
18	class MapScreen extends ConsumerStatefulWidget {
19	  const MapScreen({super.key});
20	
21	  @override
22	  ConsumerState<MapScreen> createState() => _MapScreenState();
23	}
24	
25	class _MapScreenState extends ConsumerState<MapScreen> {
26	  MapImage? _activeIcon;
27	  MapImage? _inactiveIcon;
28	  MapImage? _policeIcon;
29	  MapImage? _unknownIcon;
30	
31	  List<Checkpoint>? _pendingCheckpoints;
32	
33	  // The first confirmed GPS fix. HereMap is not rendered until this is set.
34	  GeoCoordinates? _initialLocation;
35	
36	  @override
37	  void initState() {
38	    super.initState();
39	    unawaited(_loadIcons());
40	  }
41	
42	  Future<void> _loadIcons() async {
43	    _activeIcon = await _loadImage('assets/images/marker_active.png');
44	    _inactiveIcon = await _loadImage('assets/images/marker_inactive.png');
45	    _policeIcon = await _loadImage('assets/images/marker_police.png');
46	    _unknownIcon = await _loadImage('assets/images/marker_unknown.png');
47	    if (!mounted) return;
48	
49	    final checkpoints =
50	        _pendingCheckpoints ??
51	        ref.read(checkpointNotifierProvider).value?.checkpoints ??
52	        [];
53	    if (checkpoints.isNotEmpty) {
54	      _updateMapCheckpoints(checkpoints);
55	      _pendingCheckpoints = null;
56	    }
57	  }
58	
59	  void _updateMapCheckpoints(List<Checkpoint> checkpoints) {
60	    final active = _activeIcon;
61	    final inactive = _inactiveIcon;
62	    final police = _policeIcon;
63	    final unknown = _unknownIcon;
64	
65	    if (active == null ||
66	        inactive == null ||
67	        police == null ||
68	        unknown == null) {
69	      _pendingCheckpoints = checkpoints;
70	      return;
71	    }
72	
73	    ref.read(mapControllerProvider.notifier).updateCheckpoints(checkpoints, {
74	      ContributionStatusEnum.ACTIVE: active,
75	      ContributionStatusEnum.INACTIVE: inactive,
76	      ContributionStatusEnum.POLICE_ALERT: police,
77	      ContributionStatusEnum.UNKNOWN: unknown,
78	    });
79	  }
80	
81	  Future<MapImage> _loadImage(String asset) async {
82	    final bytes = await rootBundle.load(asset);
83	    return MapImage.withPixelDataAndImageFormat(
84	      bytes.buffer.asUint8List(),
85	      ImageFormat.png,
86	    );
87	  }
88	
89	  void _onMapCreated(HereMapController hereMapController) {
90	    // Center the map instantly on the known location — no animation, no jump.
91	    final loc = _initialLocation;
92	    if (loc != null) {
93	      hereMapController.camera.lookAtPointWithMeasure(
94	        loc,
95	        MapMeasure(MapMeasureKind.distanceInMeters, 1200),
96	      );
97	    }
98	
99	    ref.read(mapControllerProvider.notifier).setController(
100	      hereMapController,
101	      _onCheckpointTapped,
102	    );
103	
104	    // Pre-warm _lastLocation in the controller so the next GPS update from
105	    // the stream doesn't trigger the fly-to animation again.
106	    if (loc != null) {
107	      ref.read(mapControllerProvider.notifier).setInitialLocation(loc);
108	    }
109	
110	    hereMapController.camera.addListener(
111	      MapCameraListener((cameraState) {
112	        ref.read(mapBearingProvider.notifier).state =
113	            cameraState.orientationAtTarget.bearing;
114	      }),
115	    );
116	  }
117	
118	  void _onCheckpointTapped(String checkpointId) {
119	    final checkpoints =
120	        ref.read(checkpointNotifierProvider).value?.checkpoints ?? [];
121	    final checkpoint =
122	        checkpoints.where((c) => c.id == checkpointId).firstOrNull;
123	    if (checkpoint != null && context.mounted) {
124	      unawaited(
125	        showModalBottomSheet<void>(
126	          context: context,
127	          isScrollControlled: true,
128	          backgroundColor: Colors.transparent,
