import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:riverpod_annotation/riverpod_annotation.dart';
import 'package:sentry_flutter/sentry_flutter.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
import 'package:ukcheckpoints_app/core/providers/location_provider.dart';
import 'package:ukcheckpoints_app/core/screens/location_permission_screen.dart';
import 'package:ukcheckpoints_app/features/auth/providers/auth_controller.dart';
import 'package:ukcheckpoints_app/features/auth/screens/forgot_password_screen.dart';
import 'package:ukcheckpoints_app/features/auth/screens/login_screen.dart';
import 'package:ukcheckpoints_app/features/auth/screens/reset_password_screen.dart';
import 'package:ukcheckpoints_app/features/auth/screens/signup_screen.dart';
import 'package:ukcheckpoints_app/features/auth/screens/splash_screen.dart';
import 'package:ukcheckpoints_app/features/billing/screens/pricing_screen.dart';
import 'package:ukcheckpoints_app/features/home/screens/main_wrapper_screen.dart';
import 'package:ukcheckpoints_app/features/profile/screens/settings_screen.dart';

part 'router.g.dart';

class RouterListenable extends ChangeNotifier {
  final Ref _ref;
  RouterListenable(this._ref) {
    _ref.listen(authControllerProvider, (previous, next) {
      notifyListeners();
    });
    _ref.listen(locationControllerProvider, (previous, next) {
      notifyListeners();
    });
  }
}

@riverpod
GoRouter router(Ref ref) {
  final listenable = RouterListenable(ref);

  return GoRouter(
    initialLocation: '/',
    refreshListenable: listenable,
    observers: [SentryNavigatorObserver()],
    debugLogDiagnostics: false,
    redirect: (context, state) {
      final authState = ref.read(authControllerProvider);

      if (authState.isLoading && !authState.hasValue) {
        return null;
      }

      final user = authState.value;
      final location = state.matchedLocation;

      final isAuthRoute =
          location == '/login' ||
          location == '/signup' ||
          location == '/forgot-password' ||
          location == '/reset-password';

      if (user == null) {
        return isAuthRoute ? null : '/login';
      }

      final status = user.profile.subscription.status;
      final isSubscribed =
          status == SubscriptionDetailsStatusEnum.ACTIVE ||
          status == SubscriptionDetailsStatusEnum.TRIALING;

      if ((user.showPaywall || !isSubscribed) && location != '/pricing') {
        return '/pricing';
      }

      final locationState = ref.read(locationControllerProvider);
      final needsLocation =
          locationState != LocationState.granted &&
          locationState != LocationState.unknown;

      if (isSubscribed && !user.showPaywall) {
        if (needsLocation) {
          return location == '/location-permission'
              ? null
              : '/location-permission';
        }

        if (isAuthRoute ||
            location == '/pricing' ||
            location == '/' ||
            location == '/location-permission') {
          return '/home';
        }
      }

      return null;
    },
    routes: [
      GoRoute(path: '/', builder: (context, state) => const SplashScreen()),
      GoRoute(path: '/login', builder: (context, state) => const LoginScreen()),
      GoRoute(
        path: '/signup',
        builder: (context, state) => const SignUpScreen(),
      ),
      GoRoute(
        path: '/forgot-password',
        builder: (context, state) => const ForgotPasswordScreen(),
      ),
      GoRoute(
        path: '/reset-password',
        builder: (context, state) {
          final token = state.uri.queryParameters['token'] ?? '';
          return ResetPasswordScreen(token: token);
        },
      ),
      GoRoute(
        path: '/pricing',
        builder: (context, state) => const PricingScreen(),
      ),
      GoRoute(
        path: '/location-permission',
        builder: (context, state) => const LocationPermissionScreen(),
      ),
      GoRoute(path: '/home', builder: (context, state) => const MainWrapper()),
      GoRoute(
        path: '/settings',
        builder: (context, state) => const SettingsScreen(),
      ),
    ],
  );
}

