  // Slate accent ramp
  static const Color slate50 = Color(0xFFE8EEFB);
  static const Color slate100 = Color(0xFFCFDAF7);
  static const Color slate500 = Color(0xFF1F5DD8); // ★ accent
  static const Color slate600 = Color(0xFF1A4FB8);

  // Semantic status
  static const Color success = Color(0xFF1F7A4D);
  static const Color successSubtle = Color(0xFFDFF1E6);
  static const Color warning = Color(0xFFB45309);
  static const Color warningSubtle = Color(0xFFFCEAC8);
  static const Color danger = Color(0xFFB42318);
  static const Color dangerSubtle = Color(0xFFFCE6E1);
  static const Color info = Color(0xFF1F5DD8);
  static const Color infoSubtle = Color(0xFFE8EEFB);

  // Surfaces
  static const Color bg = stone50;
  static const Color bgRaised = Color(0xFFFFFFFF);
  static const Color bgSubtle = Color(0xFFEFF2F5);

  // Borders (opaque — simpler than semi-transparent for dark mode later)
  static const Color border = Color(0xFFE3E6EB);
  static const Color borderStrong = Color(0xFFC8CDD4);

  // Text
  static const Color textPrimary = stone900;
  static const Color textSecondary = Color(0xFF5A6573);
  static const Color textTertiary = Color(0xFF8B95A2);

  // Accent
  static const Color accent = slate500;
  static const Color accentHover = slate600;
  static const Color accentSubtle = slate50;

  // Domain
  static const Color plateYellow = Color(0xFFFFD307);
}

// ─── Spacing ──────────────────────────────────────────────────

abstract final class ThemeSpacing {
  static const double sp1 = 4;
  static const double sp2 = 8;
  static const double sp3 = 12;
  static const double sp4 = 16; // ★ screen edge — sacred
  static const double sp5 = 20;
  static const double sp6 = 24;
  static const double sp8 = 32;
  static const double sp10 = 40;
  static const double sp12 = 48;
  static const double sp16 = 64;
}

// ─── Radius ───────────────────────────────────────────────────

abstract final class ThemeRadius {
  static const double rXs = 4;
  static const double rSm = 6;
  static const double rMd = 8;
  static const double rLg = 12;
  static const double rXl = 16;
  static const double r2xl = 22;
  static const double rFull = 999;

  static final BorderRadius brXs = BorderRadius.circular(rXs);
  static final BorderRadius brSm = BorderRadius.circular(rSm);
  static final BorderRadius brMd = BorderRadius.circular(rMd);
  static final BorderRadius brLg = BorderRadius.circular(rLg);
  static final BorderRadius brXl = BorderRadius.circular(rXl);
  static final BorderRadius br2xl = BorderRadius.circular(r2xl);
  static final BorderRadius brFull = BorderRadius.circular(rFull);
}

// ─── Shadows ──────────────────────────────────────────────────

abstract final class ThemeShadows {
  static const List<BoxShadow> sm = [
    BoxShadow(blurRadius: 2, offset: Offset(0, 1), color: Color(0x140E141B)),
  ];
  static const List<BoxShadow> md = [
    BoxShadow(blurRadius: 6, offset: Offset(0, 2), color: Color(0x140E141B)),
    BoxShadow(blurRadius: 12, offset: Offset(0, 4), color: Color(0x140E141B)),
  ];
  static const List<BoxShadow> lg = [
    BoxShadow(blurRadius: 24, offset: Offset(0, -4), color: Color(0x1A0E141B)),
    BoxShadow(blurRadius: 8, offset: Offset(0, 2), color: Color(0x100E141B)),
  ];
}

// ─── Motion ───────────────────────────────────────────────────

abstract final class ThemeMotion {
  static const Duration durFast = Duration(milliseconds: 120);
  static const Duration durBase = Duration(milliseconds: 220);
  static const Duration durSlow = Duration(milliseconds: 380);
  static const Duration durSlower = Duration(milliseconds: 500);

  /// Ease-in-out — data transitions, color changes, sheets.
  static const Curve smooth = Cubic(0.4, 0.0, 0.2, 1.0);

  /// Spring overshoot — toggles, drawers, physical interactions.
  static const Curve spring = Cubic(0.34, 1.56, 0.64, 1.0);

  /// Enter — elements arriving on screen.
  static const Curve easeOut = Cubic(0.0, 0.0, 0.2, 1.0);

  /// Exit — elements leaving screen.
  static const Curve easeIn = Cubic(0.4, 0.0, 1.0, 1.0);
}

// ─── Text styles ─────────────────────────────────────────────
// Static consts so widgets can use them with const constructors.

abstract final class ThemeText {
  static const TextStyle title1 = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 22,
    fontWeight: FontWeight.w500,
    height: 1.25,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle title2 = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 18,
    fontWeight: FontWeight.w500,
    height: 1.3,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle headline = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 16,
    fontWeight: FontWeight.w500,
    height: 1.4,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle body = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 15,
    fontWeight: FontWeight.w400,
    height: 1.5,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle callout = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 14,
    fontWeight: FontWeight.w500,
    height: 1.4,
    color: ThemeColors.textPrimary,
  );
  static const TextStyle subheadline = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 13,
    fontWeight: FontWeight.w400,
    height: 1.45,
    color: ThemeColors.textSecondary,
  );
  static const TextStyle footnote = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 12,
    fontWeight: FontWeight.w400,
    height: 1.4,
    color: ThemeColors.textTertiary,
  );
  static const TextStyle eyebrow = TextStyle(
    fontFamily: ThemeFonts.ui,
    fontSize: 11,
    fontWeight: FontWeight.w500,
    letterSpacing: 0.8,
    color: ThemeColors.textTertiary,
  );
}

// ─── MaterialApp theme ────────────────────────────────────────

abstract final class AppTheme {
  static ThemeData get light {
    return ThemeData(
      useMaterial3: true,
      fontFamily: ThemeFonts.ui,
      scaffoldBackgroundColor: ThemeColors.bg,
      primaryColor: ThemeColors.accent,

      colorScheme: const ColorScheme.light(
        primary: ThemeColors.accent,
        onPrimary: Colors.white,
        secondary: ThemeColors.textSecondary,
        onSecondary: Colors.white,
        error: ThemeColors.danger,
        onError: Colors.white,
        surface: ThemeColors.bgRaised,
        onSurface: ThemeColors.textPrimary,
      ),

      textTheme: const TextTheme(
        displayLarge: TextStyle(
          fontFamily: ThemeFonts.display,
          fontSize: 32,
          fontWeight: FontWeight.w600,
          color: ThemeColors.textPrimary,
          letterSpacing: -0.5,
        ),
        displayMedium: TextStyle(
          fontFamily: ThemeFonts.display,
          fontSize: 24,
          fontWeight: FontWeight.w600,
          color: ThemeColors.textPrimary,
          letterSpacing: -0.3,
        ),
        titleLarge: ThemeText.title1,
        titleMedium: ThemeText.headline,
        bodyLarge: ThemeText.body,
        bodyMedium: ThemeText.callout,
        bodySmall: ThemeText.subheadline,
        labelSmall: ThemeText.eyebrow,
      ),

      elevatedButtonTheme: ElevatedButtonThemeData(
        style: ElevatedButton.styleFrom(
          backgroundColor: ThemeColors.accent,
          foregroundColor: Colors.white,
          elevation: 0,
          shadowColor: Colors.transparent,
          padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 12),
          shape: RoundedRectangleBorder(borderRadius: ThemeRadius.brMd),
          textStyle: ThemeText.callout.copyWith(color: Colors.white),
        ).copyWith(overlayColor: WidgetStateProperty.all(Colors.black12)),
      ),

      textButtonTheme: TextButtonThemeData(
        style: TextButton.styleFrom(
          foregroundColor: ThemeColors.textSecondary,
          padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 12),
          shape: RoundedRectangleBorder(borderRadius: ThemeRadius.brMd),
          textStyle: ThemeText.callout,
        ),
      ),

      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: ThemeColors.bgRaised,
        contentPadding: const EdgeInsets.symmetric(
          horizontal: 14,
          vertical: 12,
        ),
        hintStyle: ThemeText.body.copyWith(color: ThemeColors.textTertiary),
        labelStyle: ThemeText.callout,
        enabledBorder: OutlineInputBorder(
          borderRadius: ThemeRadius.brMd,
          borderSide: const BorderSide(color: ThemeColors.borderStrong),
        ),
        focusedBorder: OutlineInputBorder(
