        errorBorder: OutlineInputBorder(
          borderRadius: ThemeRadius.brMd,
          borderSide: const BorderSide(color: ThemeColors.danger),
        ),
        focusedErrorBorder: OutlineInputBorder(
          borderRadius: ThemeRadius.brMd,
          borderSide: const BorderSide(color: ThemeColors.danger, width: 1.5),
        ),
      ),

      cardTheme: CardThemeData(
        color: ThemeColors.bgRaised,
        elevation: 0,
        margin: EdgeInsets.zero,
        shape: RoundedRectangleBorder(
          borderRadius: ThemeRadius.brLg,
          side: const BorderSide(color: ThemeColors.border),
        ),
      ),

      dividerTheme: const DividerThemeData(
        color: ThemeColors.border,
        thickness: 1,
        space: 24,
      ),

      navigationBarTheme: NavigationBarThemeData(
        backgroundColor: ThemeColors.bgRaised,
        indicatorColor: ThemeColors.accentSubtle,
        elevation: 0,
        surfaceTintColor: Colors.transparent,
        iconTheme: WidgetStateProperty.resolveWith((states) {
          if (states.contains(WidgetState.selected)) {
            return const IconThemeData(color: ThemeColors.accent, size: 24);
          }
          return const IconThemeData(color: ThemeColors.stone500, size: 24);
        }),
        labelTextStyle: WidgetStateProperty.resolveWith((states) {
          if (states.contains(WidgetState.selected)) {
            return const TextStyle(
              fontFamily: ThemeFonts.ui,
              fontSize: 11,
              fontWeight: FontWeight.w500,
              letterSpacing: 0.5,
              color: ThemeColors.accent,
            );
          }
          return const TextStyle(
            fontFamily: ThemeFonts.ui,
            fontSize: 11,
            fontWeight: FontWeight.w500,
            letterSpacing: 0.5,
            color: ThemeColors.stone500,
          );
        }),
      ),

      switchTheme: SwitchThemeData(
        thumbColor: WidgetStateProperty.all(Colors.white),
        trackColor: WidgetStateProperty.resolveWith((states) {
          if (states.contains(WidgetState.selected)) return ThemeColors.accent;
          return ThemeColors.borderStrong;
        }),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';
import 'package:ukcheckpoints_app/features/checkpoints/providers/nearby_checkpoint_provider.dart';

class NearbyCheckpointPopup extends ConsumerWidget {
  const NearbyCheckpointPopup({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final nearby = ref.watch(nearbyCheckpointProvider);
    if (nearby == null) return const SizedBox.shrink();

    final cp = nearby.checkpoint;
    final status = cp.contributions.isNotEmpty
        ? cp.contributions.first.status
        : ContributionStatusEnum.UNKNOWN;

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: ThemeSpacing.sp4),
      child: Container(
        padding: const EdgeInsets.all(ThemeSpacing.sp4),
        decoration: BoxDecoration(
          color: ThemeColors.bgRaised,
          borderRadius: ThemeRadius.brLg,
          border: Border.all(color: ThemeColors.border),
          boxShadow: ThemeShadows.lg,
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Container(
                  width: 8,
                  height: 8,
                  decoration: BoxDecoration(
                    color: _statusColor(status),
                    shape: BoxShape.circle,
                  ),
                ),
                const SizedBox(width: ThemeSpacing.sp2),
                const Text(
                  'Nearby Checkpoint',
                  style: TextStyle(
                    fontFamily: ThemeFonts.ui,
                    fontSize: 11,
                    fontWeight: FontWeight.w500,
                    letterSpacing: 0.5,
                    color: ThemeColors.textTertiary,
                  ),
                ),
                const Spacer(),
                SizedBox(
                  width: 28,
                  height: 28,
                  child: IconButton(
                    icon: const Icon(Icons.close, size: 16),
                    onPressed: () {
                      ref.read(nearbyCheckpointProvider.notifier).dismiss();
                    },
                    splashRadius: 14,
                    color: ThemeColors.textTertiary,
                  ),
                ),
              ],
            ),
            const SizedBox(height: ThemeSpacing.sp2),
            Text(
              cp.name,
              style: ThemeText.headline,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
            const SizedBox(height: 2),
            Text(
              'Status: ${status.name}',
              style: ThemeText.subheadline,
            ),
            const SizedBox(height: ThemeSpacing.sp3),
            Text(
              'Confirm status if possible',
              style: ThemeText.footnote,
            ),
            const SizedBox(height: ThemeSpacing.sp3),
            Row(
              children: [
                Expanded(
                  child: SizedBox(
                    height: 44,
                    child: ElevatedButton(
                      onPressed: () {
                        ref
                            .read(checkpointNotifierProvider.notifier)
                            .contribute(cp.id, ContributionStatusEnum.ACTIVE);
                        ref
                            .read(nearbyCheckpointProvider.notifier)
                            .dismiss();
                      },
                      style: ElevatedButton.styleFrom(
                        backgroundColor: ThemeColors.danger,
                        foregroundColor: Colors.white,
                        elevation: 0,
                        shape: RoundedRectangleBorder(
                          borderRadius: ThemeRadius.brMd,
                        ),
                      ),
                      child: const Text('Active'),
                    ),
                  ),
                ),
                const SizedBox(width: ThemeSpacing.sp2),
                Expanded(
                  child: SizedBox(
                    height: 44,
                    child: OutlinedButton(
                      onPressed: () {
                        ref
                            .read(checkpointNotifierProvider.notifier)
                            .contribute(
                              cp.id,
                              ContributionStatusEnum.INACTIVE,
                            );
                        ref
                            .read(nearbyCheckpointProvider.notifier)
                            .dismiss();
                      },
                      style: OutlinedButton.styleFrom(
                        foregroundColor: ThemeColors.success,
                        side: const BorderSide(color: ThemeColors.success),
                        shape: RoundedRectangleBorder(
                          borderRadius: ThemeRadius.brMd,
                        ),
                      ),
                      child: const Text('Clear'),
                    ),
                  ),
                ),
                const SizedBox(width: ThemeSpacing.sp2),
                Expanded(
                  child: SizedBox(
                    height: 44,
                    child: TextButton(
                      onPressed: () {
                        ref
                            .read(nearbyCheckpointProvider.notifier)
                            .dismiss();
                      },
                      child: const Text('Unknown'),
                    ),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Color _statusColor(ContributionStatusEnum? status) {
    return switch (status) {
      ContributionStatusEnum.ACTIVE => ThemeColors.danger,
      ContributionStatusEnum.INACTIVE => ThemeColors.success,
      ContributionStatusEnum.POLICE_ALERT => const Color(0xFFFF9500),
      _ => ThemeColors.stone400,
    };
  }
}

